import { test, expect } from '@playwright/test';

test.describe('Promo Code Application and Discounted Total Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should apply promo code and display discounted total', async ({ page }) => {
    // Verify promo code input field is visible
    const promoCodeInput = page.getByLabel('Promo Code');
    await expect(promoCodeInput).toBeVisible();

    // Verify discounted total display is visible
    const discountedTotal = page.getByRole('heading', { name: /discounted total/i });
    await expect(discountedTotal).toBeVisible();

    // Verify apply button is visible and enabled
    const applyButton = page.getByRole('button', { name: /apply/i });
    await expect(applyButton).toBeVisible();

    // Verify promo code input is focused
    await expect(promoCodeInput).toHaveFocus();

    // Enter a valid promo code
    await promoCodeInput.fill('SAVE10');

    // Verify apply button is now enabled
    await expect(applyButton).toBeEnabled();

    // Click apply button
    await applyButton.click();

    // Verify discounted total is displayed
    await expect(discountedTotal).toBeVisible();

    // Verify discounted total value is correct
    const discountedTotalValue = page.getByText(/discounted total: \$19.99/i);
    await expect(discountedTotalValue).toBeVisible();

    // Verify original total is still visible
    const originalTotal = page.getByText(/original total: \$29.99/i);
    await expect(originalTotal).toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/promo code applied successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify checkout button is now enabled
    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).toBeEnabled();

    // Verify checkout button is visible
    await expect(checkoutButton).toBeVisible();
  });

  test('should handle invalid promo code and display error message', async ({ page }) => {
    // Verify promo code input is visible
    const promoCodeInput = page.getByLabel('Promo Code');
    await expect(promoCodeInput).toBeVisible();

    // Verify error message is not visible
    const errorMessage = page.getByText(/invalid promo code/i);
    await expect(errorMessage).not.toBeVisible();

    // Enter an invalid promo code
    await promoCodeInput.fill('INVALID123');

    // Verify apply button is now disabled
    const applyButton = page.getByRole('button', { name: /apply/i });
    await expect(applyButton).not.toBeEnabled();

    // Verify error message is displayed
    await expect(errorMessage).toBeVisible();

    // Verify original total is still visible
    const originalTotal = page.getByText(/original total: \$29.99/i);
    await expect(originalTotal).toBeVisible();

    // Verify discounted total is not displayed
    const discountedTotal = page.getByRole('heading', { name: /discounted total/i });
    await expect(discountedTotal).not.toBeVisible();

    // Verify apply button is still visible
    await expect(applyButton).toBeVisible();
  });
});
